import { queryStringParams } from '../../services/query-string';
import { cabinetConfig as DKCabinetConfig } from './dk-cabinet-config';
import { cabinetConfig as ESCabinetConfig } from './es-cabinet-config';
import { cabinetConfig as ITCabinetConfig } from './it-cabinet-config';
import { cabinetConfig as SECabinetConfig } from './se-cabinet-config';
import { cabinetConfig as UKCabinetConfig } from './uk-cabinet-config';
export function getCabinetConfig() {
    const region = queryStringParams.locale;

    switch (region) {
        case 'dk-dk':
            return DKCabinetConfig();
        case 'es-es':
            return ESCabinetConfig();
        case 'it-it':
            return ITCabinetConfig();
        case 'se-se':
            return SECabinetConfig();
        default:
            return UKCabinetConfig();
    }
}

